check.model_answer:
int nextStop(Set<Integer> requests, int current) {
    int best = -1;
    for (int station : requests) {
        int distance = Math.abs(station - current);
        if (best == -1 || distance < Math.abs(best - current)
                || (distance == Math.abs(best - current) && station < best)) {
            best = station;
        }
    }
    return best;
}
